@Entity
data class Post(
    @PrimaryKey val id: Long,
    val authorId: Long,
    val title: String,
)

@Entity
data class Author(@PrimaryKey val id: Long, val name: String)

data class PostWithAuthor(
    @Embedded val post: Post,
    @Relation(parentColumn = "authorId", entityColumn = "id")
    val author: Author,
)

@Dao
interface PostDao {
    @Transaction
    @Query("SELECT * FROM posts ORDER BY id DESC")
    fun observePosts(): Flow<List<PostWithAuthor>>   // re-emits on any posts/authors change
}

