@Entity
data class Article(
    @PrimaryKey val id: Long,
    val title: String,
    val body: String,
)

@Fts4(contentEntity = Article::class)
@Entity
data class ArticleFts(
    val title: String,
    val body: String,
)

@Dao
interface ArticleFtsDao {
    @Query("SELECT * FROM articleFts WHERE articleFts MATCH :query")
    suspend fun search(query: String): List<ArticleFts>

    // Rank by relevance, joining back to the full row
    @Query("""
        SELECT * FROM articleFts JOIN articles ON articleFts.rowid = articles.id
        WHERE articleFts MATCH :query ORDER BY bm25(articleFts)
    """)
    suspend fun searchRanked(query: String): List<Article>
}

